import re
s=open('disc_main_patched.css',encoding='utf-8').read()
def ctx(pos):
    pre=s[:pos]; stack=[]
    for mm in re.finditer(r'@media[^{]*\{|[{}]', pre):
        t=mm.group(0)
        if t.startswith('@media'): stack.append([t,0])
        elif t=='{':
            if stack: stack[-1][1]+=1
        else:
            if stack:
                if stack[-1][1]==0: stack.pop()
                else: stack[-1][1]-=1
    return ' '.join(x[0] for x in stack)
