.apruve{
  position: fixed;
  inset: 0;
  z-index: 100002;
  display: none;
}

.apruve.is-open{ display: block; }

.apruve__overlay{
  position: absolute;
  inset: 0;
  background: rgba(13,13,13,.55);
}

