  position: relative;
  width: 85vw;
  margin: 60px auto;
  background: #fff;
  border-radius: 24px;
  box-shadow: 0 40px 120px rgba(0,0,0,.28);
  overflow: hidden;

  padding: 56px 72px 44px;
}

.apruve__close{
  position: absolute;
  top: 18px;
  right: 18px;
  width: 46px;
  height: 46px;
  border: 0;
  border-radius: 999px;
  background: rgba(13,13,13,.06);
  cursor: pointer;
}

.apruve__close::before,
.apruve__close::after{
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 22px;
  height: 2px;
  background: #8B8B8B;
  transform-origin: center;
}

.apruve__close::before{ transform: translate(-50%,-50%) rotate(45deg); }
.apruve__close::after{  transform: translate(-50%,-50%) rotate(-45deg); }

