/* ===== wizard modal ===== */
.disc-modal{position:fixed;inset:0;z-index:100001;display:none}
.disc-modal.is-open{display:block}
.disc-modal__overlay{position:absolute;inset:0;background:rgba(0,0,0,.55);cursor:pointer}
.disc-modal__dialog{position:relative;width:min(1240px,calc(100% - 64px));margin:56px auto;background:#fff;border-radius:22px;box-shadow:0 40px 120px rgba(0,0,0,.28);overflow:hidden;max-height:90vh;display:flex;flex-direction:column}
.disc-modal__close{position:absolute;top:24px;right:24px;width:48px;height:48px;border:0;background:transparent;font-size:0;cursor:pointer;opacity:.55;z-index:3}
.disc-modal__close::before,.disc-modal__close::after{content:"";position:absolute;left:50%;top:50%;width:38px;height:2px;background:#7A7A7A;transform-origin:center}
.disc-modal__close::before{transform:translate(-50%,-50%) rotate(45deg)}
.disc-modal__close::after{transform:translate(-50%,-50%) rotate(-45deg)}
.disc-modal__head{padding:48px 56px 18px;text-align:center;flex:0 0 auto}
.disc-modal__title{color:#0F0F0F;text-align:center;font-family:var(--font-accent);font-size:30px;font-weight:700;line-height:62.5px}
.disc-modal__sub{color:#272727;font-size:18px;font-weight:400;line-height:normal}
.disc-modal__lead{margin-top:22px;color:#409C54;text-align:center;font-size:22px;font-weight:400;line-height:normal}
.disc-modal__tabs{padding:0 56px 8px;display:flex;gap:8px;justify-content:center;flex:0 0 auto}
.disc-tab{border:0;background:#EAF2FA;color:#2C2C2C;border-radius:10px;padding:14px 18px;font-size:22px;line-height:1;cursor:pointer}
.disc-tab.is-active{background:#1F5BD6;color:#fff}
.disc-modal__body{padding:16px 56px 32px;background:#fff;flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;scrollbar-width:none;-ms-overflow-style:none}
.disc-modal__body::-webkit-scrollbar{width:0;height:0;display:none}
.disc-pane{display:none}
.disc-pane.is-active{display:block}
.disc-grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:18px}
.disc-card{border:1px solid rgba(0,0,0,.18);border-radius:10px;overflow:hidden;background:#fff}
.disc-card__title{padding:16px 18px;font-size:26px;font-weight:800;color:#1C1C1C}
.disc-card__foot{padding:16px 18px;font-size:24px;font-weight:800;color:#1C1C1C}
.disc-list{list-style:none;margin:0 20px;padding:0;border:1px solid rgba(0,0,0,.12)}
.disc-item{position:relative;padding:18px 48px 18px 18px;font-size:20px;color:#2C2C2C;border-top:1px solid rgba(0,0,0,.12);cursor:grab;user-select:none;background:#fff;touch-action:none}
.disc-handle{position:absolute;right:12px;top:50%;transform:translateY(-50%);width:28px;height:28px;display:flex;align-items:center;justify-content:center;cursor:grab;user-select:none;touch-action:none;opacity:.75}
.disc-handle:hover{opacity:1}
.disc-handle svg{display:block;width:16px;height:16px}
.disc-item.is-dragging{opacity:.55;cursor:grabbing}
.disc-item.is-over{outline:2px dashed rgba(31,91,214,.45);outline-offset:-6px}
.disc-item.is-dragging .disc-handle{cursor:grabbing}
.disc-item:first-child{border-top:0}
.disc-progress{margin:26px 56px 0;height:18px;border-radius:999px;background:rgba(0,0,0,.08);overflow:hidden;flex:0 0 auto;position:sticky;bottom:86px;background-clip:padding-box;z-index:5}
.disc-progress{background:rgba(0,0,0,.08)}
.disc-progress__bar{height:100%;width:0;border-radius:999px;background:#6FE28A;transition:width .2s ease}
.disc-actions{margin:0 56px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex:0 0 auto;position:sticky;bottom:0;background:#fff;z-index:5;padding-top:14px;padding-bottom:16px}
.disc-btn{border:1px solid rgba(0,0,0,.22);border-radius:999px;padding:16px 42px;font-size:24px;cursor:pointer;background:#fff;color:#1C1C1C}
.disc-btn--ghost{background:#fff}
.disc-btn--primary{border-color:transparent;background:#3A944A;color:#fff}
.disc-btn:disabled{opacity:.45;cursor:not-allowed}
.disc-btn:hover:not(:disabled){filter:brightness(1.05)}
@media (min-width:1101px){.disc-modal__body{padding-bottom:32px}}
@media (min-width:1025px) and (max-width:1440px){
  .disc-progress{display:none}
  .disc-actions{padding-top:10px}
  .disc-modal__body{padding-top:0}
  .disc-modal__head{padding-top:26px}
  .disc-modal__dialog{margin:5px auto;max-height:98vh;width:min(1240px,calc(100% - 64px))}
  .disc-grid3{gap:16px}
}
@media (max-width:1200px) and (max-height:850px){
  .disc-item{font-size:16px;padding:10px 44px 10px 10px}
  .disc-card__title,.disc-card__foot{font-size:18px;padding:16px}
  .disc-modal__lead{font-size:18px;margin-top:10px}
  .disc-modal__body{padding-bottom:0}
  .disc-actions{padding-top:0}
  .disc-tab{font-size:18px}
}
@media (max-width:1100px){
  .disc-modal__dialog{width:100%;height:100vh;max-height:100vh;margin:0;border-radius:0}
  .disc-modal__close{top:16px;right:16px}
  .disc-modal__head{padding:28px 18px 12px}
  .disc-modal__body{padding:12px 18px 0;padding-bottom:66px!important;touch-action:pan-y}
  .disc-modal__tabs{padding:0 18px 10px;justify-content:flex-start!important;flex-wrap:nowrap!important;overflow-x:auto!important;overflow-y:hidden!important;-webkit-overflow-scrolling:touch;gap:10px;margin:0!important;scroll-behavior:smooth;scroll-snap-type:x proximity;scroll-padding-left:18px;scroll-padding-right:18px}
  .disc-modal__tabs::-webkit-scrollbar{height:0}
  .disc-modal__tabs::before,.disc-modal__tabs::after{content:"";flex:0 0 18px}
  .disc-tab{flex:0 0 auto;white-space:nowrap;scroll-snap-align:start;touch-action:pan-x;font-size:18px;padding:12px 14px}
  .disc-grid3{grid-template-columns:1fr;gap:14px}
  .disc-btn{font-size:20px;padding:14px 24px;max-width:100%}
  .disc-progress{position:static;margin:14px 18px 0!important;background:rgba(0,0,0,.08)!important}
  .disc-actions{position:static;margin:16px 18px 18px!important;background:#fff!important;padding:0!important;flex:0 0 auto}
  .disc-item{font-size:18px}
}
@media (max-width:640px){
  .disc-modal__dialog{width:calc(100% - 16px);margin:8px auto;max-height:calc(100vh - 16px);border-radius:14px}
  .disc-modal__body{padding:16px}
}
@media (max-width:768px){
  .disc-modal__title{font-size:25px}
  .disc-modal__sub,.disc-modal__lead{font-size:16px}
  .disc-modal__lead{margin-top:10px}
  .disc-card__title,.disc-card__foot{padding:16px;font-size:18px;font-weight:800;color:#1C1C1C}
  .disc-item{font-size:16px;padding:16px 48px 16px 16px}
  .disc-modal__title,.disc-modal__sub,.disc-modal__lead{text-align:start}
}
@media (max-width:520px){
  .disc-actions{flex-direction:column;align-items:stretch;gap:12px}
  .disc-btn{width:100%}
}

